（1）算法的基本设计思想：建立图G各顶点的入度表degree[]。选择入度为0的顶点v，将v的所有邻接点的入度减1，重复执行这个过程。若每次选中的入度为0的顶点有且仅有一个，且共进行了G.numVertices次，则意味着存在唯一的拓扑序列，返回1，否则不存在拓扑序列，或存在多个拓扑序列，返回0。（2）用C语言描述的算法：
int uniquely(MGraph G) // 判定有向图是否存在唯一的拓扑序列 { int *degree, i, j, count=0, in0=-1, prev_in0; degree=(int*)malloc(G.numVertices*sizeof(int)); for(j=0; j<G.numVertices; j++) { // 计算各顶点的入度 degree[j]=0; for(i=0; i<G.numVertices; i++) degree[j]+=G.Edge[i][j]; if(degree[j]==0) { if(in0==-1) in0=j; // 入度为0的顶点 else in0=-2; // 有多个入度为0的顶点 } } while(in0>=0) { count++; prev_in0=in0; in0=-1; for(j=0; j<G.numVertices; j++) if(G.Edge[prev_in0][j]>0) { if(--degree[j]==0) { // 邻接点入度值减1
if(in0==-1) in0=j; // 入度为0的顶点 else in0=-2; // 有多个入度为0的顶点 } } } free(degree); if(count==G.numVertices) return 1; else return 0; }
